const listDataRequests = `-- name: ListDataRequests :many
SELECT r.id, r.user_id, r.type, r.status, r.source, r.due_at, r.verified_at, r.created_at, r.completed_at,
       u.email AS user_email, u.role AS user_role
FROM data_requests r
LEFT JOIN users u ON u.id = r.user_id
WHERE ($1::data_request_type IS NULL OR r.type = $1::data_request_type)
  AND ($2::data_request_status IS NULL OR r.status = $2::data_request_status)
  AND (NOT $3::boolean OR r.status IN ('pending', 'in_progress'))
  AND (NOT $4::boolean OR (r.status IN ('pending', 'in_progress') AND r.due_at < $5::timestamptz))
  AND ($6::timestamptz IS NULL
       OR (r.created_at, r.id) < ($6::timestamptz, $7::uuid))
ORDER BY r.created_at DESC, r.id DESC
LIMIT $8
`

type ListDataRequestsParams struct {
	Type        *DataRequestType   `json:"type"`
	Status      *DataRequestStatus `json:"status"`
	OpenOnly    bool               `json:"openOnly"`
	OverdueOnly bool               `json:"overdueOnly"`
	Now         time.Time          `json:"now"`
	CursorAt    *time.Time         `json:"cursorAt"`
	CursorID    *uuid.UUID         `json:"cursorId"`
	PageSize    int32              `json:"pageSize"`
}

type ListDataRequestsRow struct {
	ID          uuid.UUID         `json:"id"`
	UserID      *uuid.UUID        `json:"userId"`
	Type        DataRequestType   `json:"type"`
	Status      DataRequestStatus `json:"status"`
	Source      DataRequestSource `json:"source"`
	DueAt       time.Time         `json:"dueAt"`
	VerifiedAt  *time.Time        `json:"verifiedAt"`
	CreatedAt   time.Time         `json:"createdAt"`
	CompletedAt *time.Time        `json:"completedAt"`
	UserEmail   *string           `json:"userEmail"`
	UserRole    *UserRole         `json:"userRole"`
}

// Liste admin, les plus récentes d'abord (curseur created_at, id). open_only : reçues ou en cours ;
// overdue_only : ouvertes et échues.
func (q *Queries) ListDataRequests(ctx context.Context, arg ListDataRequestsParams) ([]ListDataRequestsRow, error) {
	rows, err := q.db.Query(ctx, listDataRequests,
		arg.Type,
		arg.Status,
		arg.OpenOnly,
		arg.OverdueOnly,
		arg.Now,
		arg.CursorAt,
		arg.CursorID,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListDataRequestsRow
	for rows.Next() {
		var i ListDataRequestsRow
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.Type,
			&i.Status,
			&i.Source,
			&i.DueAt,
			&i.VerifiedAt,
			&i.CreatedAt,
			&i.CompletedAt,
			&i.UserEmail,
			&i.UserRole,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

